INSERT INTO public.inventory (product_id, hub_id, on_hand, reserved, batch_size, low_stock_threshold)
SELECT
  p.id, h.id,
  CASE h.code WHEN 'lagos' THEN 25 WHEN 'abuja' THEN 15 WHEN 'warehouse' THEN 40 END,
  0, 1,
  CASE h.code WHEN 'lagos' THEN 5 WHEN 'abuja' THEN 3 WHEN 'warehouse' THEN 8 END
FROM new_products p
CROSS JOIN public.hubs h;
